-- Made by tools/make-changelog.py from CHANGELOG.md; do not edit by hand.
SS.CHANGELOG = {
	{ v = "1.94", summary = "The element groups list only real elements: looks are part of the element they style.", items = { "Party is listed with the game's own frames (Default WoW / Blizzard ideas), where it belongs.", "The thin party lines and the new-style player and target cards are no longer listed as elements of their own: they are looks of the party, player and target frames, chosen in those elements' settings.", "Worn rings / trinkets is part of the build spell row and only gets its own entry (under Aethus creations) once it is detached.", "The \"Other\" group is gone, and the On counts follow the same rules." } },
	{ v = "1.93", summary = "Elements are now sized like the game's own interface, by the game's UI Scale and resolution.", items = { "New and existing layouts no longer get an extra Slim Suite size per screen shape (the 4:3, 16:9, 21:9 ... templates). Each element is its own size (1, unless you resized it) inside the game's UI Scale, exactly like the default interface. Change the game's UI Scale to make everything bigger or smaller.", "Where elements start on a new layout still follows the screen shape." } },
	{ v = "1.92", summary = "Each element group in the Interface settings can be closed, and has its own On, Off, Default and Reset for every element in it.", items = { "Click a group's name (Aethus creations, My creations, Default WoW / Blizzard ideas) or its + / - to close or open the whole group. A search still finds elements in a closed group.", "On, Off, Default and Reset buttons on each group's line change every element in that group at once, lined up with the elements' own buttons below. Each press is one step in Undo / Redo, and hovering a button says what it does." } },
	{ v = "1.91", summary = "Each group of elements shows how many are On, such as 3/5, and moving an element can no longer change its size.", items = { "The category buttons in HUD Edit Mode and the group headings in the Interface settings show how many of their elements are On out of all of them, for example \"Aethus 3/9\".", "Moving an element never changes its size. If anything changes its size or scale during a move, it is put back when you let go, and the action log notes it with the sizes before and after.", "The resize corner (+) does nothing until the mouse really moves, so grabbing near the corner to move an element can't shrink it. Its hover text says what it does, every resize is in the action log, and Undo can take it back.", "The in-game Changelog lists the newest release first.", "The search boxes in the settings and in HUD Edit Mode find elements by name and by everyday words: player, party, encounter, dps, xp, buffs and so on.", "While HUD Edit Mode is open, every scale change of an element is written to the action log with the code that made it, to track down the player and party frames shrinking at the screen edge.", "While HUD Edit Mode is open, the action log also notes when parts of an element are hidden for reaching outside its box, which can make a frame look smaller.", "The shared AZS Kit is now Slim Suite's own (SlimSuiteKit.lua). AZS Stats and AZS Handbook are discontinued, so nothing is shared with other addons any more.", "Performance: the check that keeps each element's parts inside its box runs every 2 seconds instead of twice a second while you are not editing (moves and resizes are still caught at once). Dragging the resize corner redoes only that element instead of the whole HUD every frame. Timers keep an even rhythm, and the Level Up button asks the game for its count once instead of twice.", "Every On / Off / Default change of an element is written to the action log with what asked for it, to track down elements that switch on by themselves. The action log keeps 300 lines instead of 100.", "Code cleanup: the old move panel from before HUD Edit Mode, the unused element-mode row in the settings, and nine functions nothing used any more are removed.", "The three biggest files are split by job, so each file does one thing:", "SlimSuiteWorld.lua keeps markers, encounter and target debuffs, the revive bar and the proc meter. The minimap pins, lairs and local clock moved to SlimSuiteMinimapPins.lua, combat text to SlimSuiteCombatText.lua, and boss and Guardian kills to SlimSuiteKills.lua.", "SlimSuiteFrames.lua keeps the HUD frames (Level Up, clock, encounter bars, announcements, tally). Placement and sizing moved to SlimSuitePlacement.lua, the buff frame, action bar and XP bar to SlimSuiteBars.lua, and saved places, Mirror Target and frame looks to SlimSuiteAnchors.lua.", "SlimSuiteEdit.lua keeps party and friend buffs, setting check boxes and Mirror Target. The minimap's look moved to SlimSuiteMinimapShape.lua, layouts, chat and the XP bar to SlimSuiteLayoutTools.lua, HUD Edit's size menu, grid, snapping and handles to SlimSuiteHandles.lua, and the tooltip, Reset and the target frame to SlimSuiteGameFrames.lua.", "One-time upgrades of saved settings are now one numbered list (SlimSuiteUpgrades.lua) that runs once per character after login, instead of separate timers in different files. Each upgrade is written to the action log.", "New /slim perf: measures every part of Slim Suite for 10 seconds (or /slim perf <seconds>) while you play, then lists the busiest timers with how often they ran, how long they took and how much garbage they made, plus total memory. The report also goes to the action log.", "Every push to GitHub now runs all the checks, including the real Lua 5.0 compile of every file, not only pushes that make a release.", "Every file uses the same indentation (tabs).", "Everything Slim Suite's files share now lives in Slim Suite's own table (SS.PlaceAll, SS.MOVABLE and about 100 more) instead of a hand-kept list of private names, so nothing Slim Suite makes can clash with another addon. The checks now fail if any file creates a new global name by mistake.", "About 200 lines of text that were English only are translated into Spanish, French, German, Portuguese and Italian: the hover text, short labels, warnings, help lines, element groups, Undo and Redo, the search, and older settings and messages that had been missed. The new text uses the same words as each language's existing translations (for example the German Stärkungen for buffs and Rundenzeit for the run clock, the French Chronomètre de partie, and fenêtres / avisos / telas / schermate for the level-up cards).", "Quick setup and the preset designs are removed entirely. Layouts are made by hand in HUD Edit Mode.", "The retired \"buffs on the target frame\" setting is turned off once for anyone who still had it, and the buffs go back to their own place.", "Performance: a full re-placement places only attached elements again (not every element four times). The minimap boss pins read the boss and guardian lists once a second instead of 20 times, and the kill tracker reuses its tables and saves only when a count changes, for less garbage (and fewer hitches) during a run. After login only your language's translations stay in memory. An active custom profile is saved once when a drag or resize ends instead of four times a second during it.", "The separate Minimap list in the Interface settings is removed. All of those settings are in the Minimap's own section and its right-click menu." } },
	{ v = "1.90", summary = "A new list shows every setting that joins one element into another, each element can sit over the level-up cards on its own, and the settings gain a smarter search, Reset, Undo / Redo and hover help.", items = { "New \"Optional combined that hide elements\" section in the Interface settings (/slimsuite), listing each combination and which element leaves its own place when it's on: joining the party yourself, Mirror Target, party frames joined to the player frame, buffs joined to the player frame, the worn rings / trinkets row joined to the build spells, and the local clock inside the minimap.", "Every element has a new \"Show over the level-up / new-item cards\" setting, in its right-click menu and its section, so each one can sit over the cards or under them on its own. The global setting in the Interface settings sets every element at once.", "The element sections in the Interface settings are grouped into Aethus creations, My creations and Default WoW / Blizzard ideas. The + / - now sits to the left of each name, outside the button, and pressing On no longer opens the section by itself.", "The search box at the top of the settings understands buzz words: typing hide, clock, boss, size, party and so on opens every matching element section while you type, and jumps to the page with matches.", "Each element has a Reset button next to Default. It puts back its place, size, opacity and cards setting.", "Hover text on On, Off, Default and Reset says what each one does. Long setting names are shortened, with the full sentence in the hover text.", "Undo and Redo buttons at the bottom of the settings (and /slim undo, /slim redo) step through the last 25 changes. Every change, undo and warning is written to the action log (/slim log) with its value before and after.", "Warnings in chat when settings undo each other, such as an element On at 0% opacity, or the local clock inside a minimap that is Off.", "In HUD Edit Mode, an element's right-click menu has Open in settings, which opens its section in the settings, scrolled to and flashing.", "The first time Slim Suite loads, one chat line points to /slim help, which now starts with a short getting-started guide.", "The settings window's header is cleaned up. The old \"Choose a module to open its settings\" card, which overlapped the page title, is gone. So is the second \"Slim Suite\" bar above the sidebar. The version moved to the bottom bar, the search box is labelled Search, and the \"Module enabled\" switch at the top of each page is removed, since every element has its own On / Off. A page that was switched off is switched back on once, with its earlier settings.", "A Changelog page in the settings, under Accessibility, lists every release from the first to this one, oldest first.", "\"Plater-style nameplates\" is renamed \"Slim nameplates\", so it no longer borrows another addon's name." } },
	{ v = "1.89", summary = "HUD Edit Mode replaces Toggle UI Settings, every element's settings are now in the settings window, and every element has its own opacity.", items = { "The \"Toggle UI Settings\" checkbox is now \"HUD Edit Mode\", at the top of the Interface settings. Ticking it opens HUD Edit; unticking it closes HUD Edit and locks the UI.", "Removed the separate HUD Edit Mode button further down, and the \"Recommended HUD preset\" button.", "New Elements section in the Interface settings (/slimsuite): every element is listed with On, Off and Default buttons. Choosing On opens its section, which holds every setting from its right-click menu; an element that is Off or Default stays closed.", "Every element has a new Opacity setting, from 100% (solid) to 0%, set separately for each element in its right-click menu and its section. Hiding or turning an element off still hides it completely.", "The minimap settings are reorganised: a Square / Circle choice, show or separate the local clock, caches, bosses (with new options to show their raid icon and their name), lairs and their refill timer, and turning off the game's nearest Guardian lair flag.", "New minimap options to hide the day / night (sun and moon) button, the zone name and its X button, and the + / - zoom buttons, in the minimap's section, its right-click menu and the Gameplay settings.", "Removed the info drawer element entirely.", "Removed the Transparent minimap option; per-element Opacity replaces it. Anyone who had it on gets the normal minimap back." } },
	{ v = "1.88", summary = "Slim Suite no longer changes other addons, dropdown buttons lose their trailing \"v\", and sound previews can be paused.", items = { "Removed the \"Other addons\" section and its Azeroth Stats option, which ran Azeroth Stats' /azstats bar command to hide its top bar. Slim Suite no longer changes Azeroth Stats' settings.", "Dropdown buttons (option choices, Chain to, Presets) no longer end in a \"v\".", "Sound previews can be paused: the button stops the preview at once, and starting another preview stops the one playing. Previews now play on the music channel (the game's music pauses for a moment); with music off they play as before." } },
	{ v = "1.87", summary = "Joined elements now hide and turn off together, and Quick setup is put away for now in favour of HUD Edit.", items = { "Hiding or turning off the build spell row also hides or turns off the worn rings / trinkets row while the two are joined, and the other way round. Showing or turning on either one brings back both.", "The same goes for any element pinned to another one. Detached rows stay separate.", "Quick setup and its preset designs are hidden for now: the Quick button in HUD Edit and /slim quick are gone, and HUD Edit's search box uses the space." } },
	{ v = "1.86", summary = "Better tracking for elements that won't stay hidden, and designs no longer leave elements in an unset state.", items = { "Hide feature clicks are written to the action log (/slim log), with a check one second later of whether the element really faded out, to find what undoes it.", "Applying a preset design sets every element it doesn't mention to the game's default, instead of leaving it unset." } },
	{ v = "1.85", summary = "Quick setup gets a second console design, Console B, in preset slot 5, to compare with Console A.", items = { "New Console B design (preset 5): the console layout arranged by hand in game, with huge party lines, upright boss bars top-right, a large action bar and the XP bar across the whole screen. The minimap, run clock, legendary luck, stats panel and build rows are off in it.", "Upright encounter bars follow \"Most bars shown\": with it set to 5, each bar is narrowed so all five fit in the room four used to take. Console B now shows up to five.", "Demo Mode and HUD Edit show five sample bosses instead of four.", "A disabled minimap is now hidden completely. Before, only its border faded and the map itself stayed on screen." } },
	{ v = "1.84", summary = "A new Console A design in Quick setup for controller and handheld players, a read-only info drawer, and the AI-generated demo designs are gone.", items = { "New Console A design (preset 4): the XP bar across the whole bottom edge with all seven action buttons (the racial one included) on it, your frame bottom-left and your target bottom-right just above the XP bar, large thin party lines, the compass at the top in place of the minimap, up to five encounter bars top-right and the info drawer under them.", "New Info drawer element: a read-only panel showing your damage per second, legendary chance, luck and a few stats. Turn it on and place it in HUD Edit like any other element.", "The revive bar can stand upright: a new \"Vertical\" option in its menu fills it from the bottom up, with its text above.", "The XP bar has a new \"Stretch across the whole screen\" option that keeps it full width on any resolution.", "Encounter bars have a new \"Most bars shown\" option (All, 3 or 5). With a limit set, each bar keeps its height and the frame grows downward as more bosses arrive.", "Presets now have five numbered slots, so a design can keep its place in the list.", "Removed the five AI-generated demo designs (Classic Plus, Centered, Info Column, Minimal, Controller / Handheld) and the note about them. Quick setup now offers the designs made by hand.", "The new-style player and target cards show your face in the frame's ring.", "Hide feature and Disabled now stay hidden for the party frames, the legendary luck panel and the game's player and target frames, which were being shown again by their own updates.", "\"Show every button at all times\" keeps empty action buttons visible: the game's own drag events no longer hide them again, and the racial 7th button is included.", "New /slim positions command writes where every element sits (position, size and scale) to the action log.", "Buffs joined above your frame sit tighter on it: the empty strip kept under the bottom row for timers is closed up when those buffs have no timer." } },
	{ v = "1.83", summary = "Fixes for the demo designs: the player and target cards show their art properly, and nothing covers the chat.", items = { "The new-style player and target cards use the standard unit-frame art, so they no longer show a broken, cut-off picture.", "The Controller / Handheld design no longer turns on the combat text box, which covered the chat.", "Enemy plates with large names are tall enough for the name, so stacked plates like \"Plagued Ghoul x11\" fit their box.", "The Controller / Handheld and Minimal designs keep the action bar at its normal size, so it no longer splits apart." } },
	{ v = "1.82", summary = "The five demo designs in Quick setup are now far more different from each other, each built around its own idea.", items = { "Classic Plus: the game's own frames and look, with just boss bars and a run clock added.", "Centered: everything low and central, you and your target mirrored over the action bars, your party in a row beneath.", "Info Column: run info, stats and the damage meter stacked down the left, the action bar standing up on the right.", "Minimal: almost nothing on screen, everything pushed to the edges, you and your party as one thin line.", "Controller / Handheld: big, high-contrast frames, you and your target either side of your hero, party across the top.", "Every design was checked on ten screen sizes, from 4:3 to ultrawide and the Steam Deck, so nothing overlaps and the middle stays clear." } },
	{ v = "1.81", summary = "Quick setup now comes with five demo designs that show what Slim Suite can do: Classic Plus, Centered, Info Column, Minimal, and Controller / Handheld. They're AI-generated: common layouts from WoW Forever, retail WoW and Azeroth Survivors were cross-referenced to work out what a typical UI should include, and each design was built new for Slim Suite.", items = { "Each design fits any screen, from 4:3 to ultrawide and the Steam Deck, and keeps the middle of the screen clear for the fight.", "Your own exported layouts can be added as presets and are shown before the demo designs." } },
	{ v = "1.80", summary = "New Quick setup asks how you play and sets Slim Suite up for you, party frames show who is down and how far away they are, and stacked enemy plates no longer overlap.", items = { "Quick setup (the Quick button in HUD Edit, or /slim quick): six short questions about look, how much on screen, group play, enemy plates, sounds and text size. Your answers set the matching options once; every option can still be changed by hand afterwards.", "Quick setup can offer up to five preset designs first, and each answer and preset can show an in-game picture.", "Party frames turn grey when a member is down or dead, show a revive bar on the teammate you are reviving, show their distance in yards at the top left of their face, and dim slightly when they are out of range. Each can be turned off in the party frame's right-click menu.", "Stacked enemy plates for different monsters no longer sit on top of each other, and normal and elite monsters with the same name get separate plates." } },
	{ v = "1.79", summary = "Stacked enemy plates are easier to spot.", items = { "Plates for a group of the same enemy (such as \"Plagued Ghoul x24\") now sit in a light box with a thin gold border.", "They stand out more than single enemies but stay quieter than the boss and guardian cards." } },
	{ v = "1.78", summary = "Clicking an encounter bar targets that boss or guardian again, even when it is far away.", items = { "Encounter bar clicks target the enemy by its exact name first, as they did before 1.35, then check that it is the right spawn.", "Cycling through nearby enemies is only a fallback when an ordinary mob shares the name, so clicks no longer land on random enemies." } },
	{ v = "1.77", summary = "HUD Edit shows one category at a time, party frames stop snapping by accident, and the spacing slider is easier to read.", items = { "HUD Edit has Original, Aethus, Custom and Other buttons side by side. One category's elements show below at a time.", "Party frames no longer snap onto other elements when dropped.", "Snaps are written to the action log, so accidental ones can be found with /slimsuite log.", "The party spacing slider is larger and shows its value on a labelled line.", "The Character sheet and the player and target cards keep their default look; they no longer follow the themes.", "Not yet tested in the live client: all of the above. Party member 1 still shows without its name and portrait." } },
	{ v = "1.76", summary = "The player and target cards use the game's frame art and follow the themes. The Character sheet follows the themes too.", items = { "The player and target cards match the default frames' size and bar positions.", "The cards show the game's own art for Original, and RPG or Modern panels otherwise.", "The Character sheet is no longer hidden by Setup, and it follows the RPG and Modern themes.", "Not yet tested in the live client: all of the above, including the card name and portrait, which are still approximate." } },
	{ v = "1.75", summary = "Fixes a repeating placement error, keeps chat usable during Setup, and sends frame sizes to the action log.", items = { "Fixes the repeating \"BuffFrame is dependent on this\" error when the layout is restored.", "Setup keeps the chat window and typing box usable.", "/slimsuite framesize writes its numbers to the action log (/slimsuite log).", "Not yet tested in the live client: all of the above." } },
	{ v = "1.74", summary = "Adds a party spacing slider, a frame measuring command, and fixes for the action bar, mirrored frames and Setup.", items = { "Party frames have a \"Space between players\" slider in their right-click menu (0 to 30).", "/slimsuite framesize prints the size and layout of the game's player and target frames.", "Setup no longer hides the Character element, and it opens every section of the element list.", "Action bar buttons shown at all times now work.", "Mirrored target and player frames use the same on-screen scale.", "The element menu is scaled down when attached to HUD Edit.", "Not yet tested in the live client: all of the above." } },
	{ v = "1.73", summary = "Setup in HUD Edit hides everything until you turn elements on, and HUD Edit is smaller.", items = { "Setup hides every element's handles and sample content, not only the frames. An element shows again once you enable it.", "HUD Edit is 360 by 300.", "Not yet tested in the live client: whether the top-left player frame and the luck panel stay hidden after Setup." } },
	{ v = "1.72", summary = "HUD Edit gets a Setup button, plain-English tooltips, and themes for every element.", items = { "Setup hides every element, including the game's own, so you can turn on what you want one at a time.", "Each element row has a tooltip that says what it is and what options it has.", "The RPG and Modern theme buttons set the look of every element.", "Element right-click menus attach to the HUD Edit window while it is open.", "The Collapse options button is gone, and the element list uses the space.", "Not yet tested in the live client: the new HUD Edit layout, tooltips and Setup button." } },
	{ v = "1.71", summary = "Removes the companion and the alternative Character sheet, adds RPG and Modern themes to HUD Edit, and makes HUD Edit smaller.", items = { "Removed the companion.", "Removed the alternative Character sheet. The Character element is back to Original.", "HUD Edit has RPG and Modern theme buttons. Clicking the active theme turns it off.", "HUD Edit is smaller (400 by 340).", "Not yet tested in the live client: the new HUD Edit layout and themes." } },
	{ v = "1.70", summary = "The companion shows the full figure and tries the game's own dance animation.", items = { "The companion shows the whole character, not just the head.", "Dance plays the game's dance animation on the companion only. If this client cannot play animations on the companion, the button says so.", "Not yet tested in the live client: whether the companion can dance, and which dance a Tauren gets." } },
	{ v = "1.69", summary = "Fixes the companion, which failed to load its model.", items = { "The companion now uses the unit model frame type, so it can show your character.", "Not yet tested in the live client: the dance animation number, and whether the model shows your character." } },
	{ v = "1.68", summary = "A small companion: a 3D copy of your character on screen, with a dance button.", items = { "/slimsuite companion shows or hides it. Drag it to move it; its place and whether it is shown are kept between logins.", "Dance plays an animation on the companion only. It does not change your character.", "Not yet tested in the live client: the dance animation number, which is a first guess, and whether the model shows your character." } },
	{ v = "1.67", summary = "The alternative Character sheet gets a 3D character with emote buttons, and reacts to bosses and low health.", items = { "The alternative Character sheet's layout button now reads \"Use alternative\" or \"Use original\".", "Dance and Sit buttons sit under the model and use the game's own emotes.", "The character cheers when a boss or guardian dies.", "The character cowers once when health drops below half, and can cower again after healing.", "The alternative sheet stays open but invisible while it is closed, so the model keeps running. C shows it again.", "The action log only records real changes, so repeated settings no longer fill it.", "Not yet tested in the live client: the emotes, the cower and cheer, the hidden sheet, and C." } },
	{ v = "1.66", summary = "Adds an action log, so you can send recent activity when something goes wrong.", items = { "/slimsuite log opens the action log, which keeps the last 100 actions with their times. It is kept between logins.", "Copy selects the whole log, so Ctrl+C copies it.", "Recorded: HUD Edit opening and closing, UI locking, element changes, encounter bar target clicks, snap changes, and errors Slim Suite catches.", "Not yet tested in the live client: the log window and its Copy button." } },
	{ v = "1.65", summary = "Character sheet gets a gear column with set bonuses, the compass can show the run clock, and HUD Edit Mode is tidier.", items = { "Vertical Character layout: only the model box and its stats stay. The gear stands in one column to its right.", "The necklace, both rings and both trinkets show their item names, and a set panel lists each set you wear with its 4 and 8 piece bonuses.", "The run clock can be shown along the bottom of the compass, as one line of run time, next boss and zone. It is off by default, and can be turned on from the compass's or the run clock's options.", "Chained elements always stay next to each other. The option to turn this off has been removed.", "The HUD Edit section headers are smaller.", "Not yet tested in the live client: the Character gear column and its frame names, the set panel, and the compass run clock." } },
	{ v = "1.64", summary = "HUD Edit Mode lists its elements in three sections, each of which opens and closes.", items = { "The elements are grouped as Original Unit Frames, Aethus Design and Custom Design. Anything not in a group appears in an Other section, which is hidden while it is empty.", "Each section header shows how many elements it holds. Click it to open or close the section.", "Within a section, the elements sit in three columns, filled top to bottom.", "The window is wider to fit three columns, but it is no taller.", "Not yet tested in the live client: the section headers and how the window looks at its new width." } },
	{ v = "1.63", summary = "Smaller HUD Edit Mode, and the Character sheet fixes.", items = { "HUD Edit Mode is compact again: a smaller window at its normal size, with the element list in two columns, and the grid slider, search and options placed closer together.", "The Character sheet no longer shows a gold border outside the setup.", "Character can be set to the vertical layout, with all items in one column beside the character.", "Not yet tested in the live client: the compact window's layout, and the Character vertical layout next to the stats pane." } },
	{ v = "1.62", summary = "Slim Suite does less work while you play. Layout and behaviour are unchanged, apart from the timing notes below.", items = { "The compass is checked 10 times a second and redrawn only when you move or turn, with a full refresh every half second.", "The combat-text box animates while text is on screen. When it is empty and hidden, it is checked 4 times a second.", "The choice HUD, minimap pins and world markers update less often: 10 and 20 times a second instead of every frame.", "The frame-bounds check runs 10 times a second instead of 20, and no longer creates a new table on each check. This is the largest saving.", "Match sounds are checked 10 times a second. Unit-event redraws (cards, party lines, friend buffs) run 20 times a second.", "Each language's translations are compiled only when the game needs them, rather than all six at startup.", "Trade-off: a change inside a frame that is not moving can take up to half a second to be corrected, as before. Pins and markers can lag by up to one twentieth of a second.", "In the test client, Slim Suite's per-frame work fell by about 40%. Not yet tested in the live client." } },
	{ v = "1.61", summary = "Fixes to HUD Edit Mode and to frames that were anchored to each other in a loop.", items = { "HUD Edit Mode is smaller overall, at 78% of its previous size.", "The HUD Edit Mode button now unlocks the elements, the same as Toggle UI Settings, so it works when opened by hand.", "Save writes the arrangement into the layout named on the Layout button, or creates \"HUD edit\" if there is none. Closing the window locks the UI again.", "Snapping no longer anchors two frames to each other. Saved anchors that looped back are cleared once at login, so those frames return to their default place.", "The buff frame falls back to a fixed spot if the game rejects its anchor.", "Not yet tested in the live client: the grid and element handles after a loop error, and the Save button itself." } },
	{ v = "1.60", summary = "HUD Edit Mode gets a closer look to the game's own editor, and the Talents window and the minimap do more. Everything is optional and off until you turn it on.", items = { "Toggle UI Settings opens HUD Edit Mode. The old first-time walkthrough no longer starts from that toggle; Run setup again still does.", "HUD Edit Mode has a layout picker, a grid slider, a search box, a Collapse options button and an info icon. Elements sit in two columns, and Advanced Options turns on the chain panel.", "Chaining moves a partner directly ahead of or behind its primary in the list, with Keep chained elements next to each other.", "The Move UI panel and the setup bar no longer have their own Snap switch. Snap to Elements lives only in HUD Edit Mode.", "The Character window has a vertical layout: the equipment slots stand in one column down the left, with the model beside them.", "Talents show only the trees you have points in. With one tree, the tab row is hidden.", "Gameplay has two new options: hide the Bag button, and hide the Map button on the minimap.", "Ctrl-click the minimap to enlarge it to 2.5 times its size, and Ctrl-click again to shrink it back. It is not saved.", "Not yet tested in the live client: the new HUD Edit layout, the Character vertical layout, the Talents tab filter, and the big minimap placement." } },
	{ v = "1.59", summary = "New HUD Edit Mode window, in the style of the game's own HUD editor, with one tick box per element. Duplicate element settings are removed from the addon menu.", items = { "HUD Edit Mode opens from the Interface page. Every element is listed under Frames, Combat or Misc.", "Each tick box has three states: ticked is On, empty is Off, and D is Default (the game's own element).", "Click an element's name to Revert Changes or Reset To Default Position. Revert All Changes returns every element to Default.", "Removed from the addon menu, because HUD Edit Mode covers them: the Elements page, and the separate Legendary luck, Compass and Side achievements button toggles.", "Not yet tested in the live client: the window's layout and its Show Grid and Snap to Elements checkboxes." } },
	{ v = "1.58", summary = "Slim Suite does less work while you play. Layout and behaviour are unchanged.", items = { "The check that keeps frame content inside its box now runs when a frame moves, resizes, rescales or shows or hides, plus a slow safety pass every half second. Before, it ran 20 times a second on every frame.", "In the test client, this roughly halves Slim Suite's recurring work.", "Trade-off: a change inside a frame that isn't moving can take up to half a second to be corrected." } },
	{ v = "1.57", summary = "The settings window has an Elements page listing every element with On, Off and Original buttons. Character and Talents are now elements too.", items = { "New Elements page, first in the sidebar: each element has On, Off and Original buttons. The highlighted button shows its current state. They use the same controls as edit mode.", "Character and Talents start as Original, so the game's windows are unchanged until you choose On or Off.", "On: Slim Suite places the window, and its saved place is applied each time it opens.", "Off: the window stays hidden, even when you press C or N.", "Not yet tested in the live client: dragging these two windows, and how the new settings page is laid out." } },
	{ v = "1.56", summary = "Removed arrow-key nudging, so WASD and the arrow keys work normally again. The Character and Talents windows can now be placed like other Slim Suite elements.", items = { "Edit mode no longer takes the keyboard. Drag and resize still work as before.", "Character and Talents are new movable elements. Their saved place is re-applied each time the window opens. Until you move them they keep the game's default place.", "Not yet tested in the live client: dragging these two windows may need a handle on each window." } },
	{ v = "1.55", summary = "Slim Suite can now play a sound when you help bring a downed teammate back up.", items = { "New Sounds setting: Teammate revive sound (when you helped revive them), with Off or Successful revive. It is off by default.", "It plays only when you were reviving that teammate shortly before they got up and the game reports their fall ended in a revive. Someone else's revive, a teammate leaving, a reset bar or the run ending play nothing. It plays once per fall.", "The new sound is normalized to the same loudness as the other Slim Suite sounds." } },
	{ v = "1.54", summary = "Settings are in one Slim Suite category organised by function, enemy nameplates are slimmer, and the camera distance is adjustable.", items = { "Settings window: one Slim Suite category with subcategories for Interface, Nameplates, Gameplay, Chat, Sound and Accessibility, in the look of the game's options window.", "Defaults: each subcategory has a Defaults button that resets only its own settings.", "Reset ALL: resets every Slim Suite setting, element position, look, preset and saved layout to the defaults, after a confirmation prompt, then reloads the UI.", "Element box: the Elements button on the edit bar opens a box where each element is Enabled, Disabled or Default, with all-on, all-off and all-default buttons. Right-click menus use the same flat look.", "Edit bar: a Snap switch snaps moved elements to the grid and to nearby frames. Presets are in a drop-down, and the bar fits in two rows. Demo Mode no longer shows a floating box, and elements can be edited while it runs.", "Enemy nameplates: a Plater-style option shows a slim health bar with the name above it. Its width, bar height, name size, border, health text and the colours for normal, elite and boss enemies can be changed. The boxed look is still available.", "Camera: the camera distance can be set from 5 to 50 yards in settings, or with /slim camera, which also accepts +/- steps and named presets." } },
	{ v = "1.52", summary = "Default game frames can take the RPG and New School looks, the settings window has a sidebar, and elements can be nudged with the arrow keys.", items = { "Default frames: player, target, party, buffs, experience bar, action bar and cast bar take the RPG or New School look. Original keeps the game's own frames.", "Proc meter follows its look from the right-click menu, like the other elements.", "Right-click menu: a Reset this element button puts an element back to its default place, size and look.", "Editing: arrow keys move the selected element one pixel, and Shift with an arrow key moves it ten. A gold outline marks the element being edited.", "Settings: a search box filters the settings, a Window text size choice (Normal, Large, Larger) resizes Slim Suite's windows, and a short explanation shows when you hover over some settings.", "Settings window: modules are listed in a sidebar on the left, with the module's title above its settings. Every setting is still there.", "Fix: the right-click menu no longer errors when it opens for an element by name.", "Not yet: minimap, chat and tooltip default frames, and enemy nameplates follow the global look only." } },
	{ v = "1.51", summary = "Every Slim Suite element can have its own look, and the panel styles are renamed RPG and New School.", items = { "Panel styles are now Original, RPG (the damage meter's gold-edged dark panel) and New School (the blue-tinted game tooltip panel).", "Right-click any element that supports looks: its Look button cycles Global, Original, RPG and New School. The global buttons on the edit bar and the Panel style setting set every element at once and clear the individual looks.", "Original keeps each element as it was before the panel styles. The damage meter now shows its own skin in Original and RPG; only New School hides it.", "Converted to the panel styles: stored level-up button, revive bar, combat text, side achievements button, player and target cards, raid icon panel, stats panel, announcement banner, boss encounter rows, item and spell slots, party lines, compass, damage meter, luck, tally and local clock.", "Not converted yet: enemy nameplates and the proc meter follow the global look only." } },
	{ v = "1.50", summary = "Panel styles extend to the tally and local clock, the edit bar gets its style buttons on their own row, and the legendary luck panel shows its benefits.", items = { "Tally and local clock follow the panel style: Original keeps their dark band, DPS meter and Tooltip draw the chosen panel behind them.", "Edit bar: the Original, DPS meter and Tooltip buttons sit on their own bottom row. Reset All and Done moved to the middle row to stop the overlap.", "Legendary luck: a two-step view shows your current chance and the chance with +10% luck, with the change. The grid shows six steps of 10% luck from where you are, with each chance and how many times your current chance it is." } },
	{ v = "1.49", summary = "Adds panel style buttons to the edit bar and drag-and-drop ordering for stats.", items = { "Edit bar: Original, DPS meter and Tooltip buttons beside Reset All and Done. The one in use is highlighted, and it uses the same setting as the Panel style option.", "Stats: hold the grip (==) beside a stat in its right-click menu, move over the row you want, and let go to move it there. The stats panel follows the same order, and the order is saved with your profile.", "Limits: the grip is a plain text button and the drop uses the row under the cursor when you let go." } },
	{ v = "1.48", summary = "Adds an Other addons section to the settings, starting with an option for Azeroth Stats.", items = { "Other addons (first section in settings): Azeroth Stats: hide its top bar. On by default. Slim Suite runs Azeroth Stats' /azstats bar command once per account after login, retrying briefly while the addon loads. Unticking does nothing; ticking again runs the command once more.", "Slim Suite cannot read whether the bar is hidden, so if the bar is already hidden it will show again on the first run. Tick the box again, or use /azstats bar, to hide it.", "The run-ready report cannot be turned off yet: Azeroth Stats documents no command or setting for it." } },
	{ v = "1.47", summary = "Adds a Panel style setting for Slim Suite's own panels, with the damage meter and luck panel as the first group to follow it.", items = { "Panel style (Everywhere section): Original (game tooltip look), DPS meter (the meter's gold-edged dark panel), or Tooltip (blue-tinted game tooltip panel). Blizzard's own frames are never restyled by this setting.", "Damage meter and legendary luck panel follow the chosen style. The enemy nameplates follow it too.", "Other Slim Suite elements keep their current look until their group is converted.", "Backup: git tag backup/1.46-before-panel-style marks the last 1.46 commit." } },
	{ v = "1.46", summary = "Chat filters, a cleaner stats panel, sleeker combat text, sound silenced while paused, and grouped monster nameplates.", items = { "Stats panel: the category menu is gone. Every stat is in one list with its own switch, an icon, its own colour, and a hover description. Values flash green or red when they change, and any numeric stat the game sends that Slim Suite doesn't name yet is shown too.", "Chat mods: new toggles for addon text, location lines (\"enters ... Move to begin\"), difficulty lines, and talent experience. The racial filter now covers every race's racial ability names from the Armory.", "Damage text: rows renamed to say what they do, world damage choices reworded, numbers smaller, icons with a dark backing (gold ring on crits), and crits larger and heavier.", "Sound: nothing starts while the game is paused or the Esc menu is open. Death sounds that were waiting are held until the pause ends. A sound already playing finishes.", "Enemy nameplates: identical monsters share one plate with a count and their combined health (for example, Spider x34). A new setting turns grouping off.", "Tests: new chat filter scenario; combat box size expectation updated." } },
	{ v = "1.45", summary = "", items = { "Restyled sound previews with white play/pause-style icons and hover highlighting. Supported clients stop the previous preview before switching; legacy clients queue the latest request without overlap. True pause/resume remains unavailable on the inspected client.", "Disabled the temporary card-selection item footer while retaining its implementation and normal build-row preferences. Independent Stats edge placement and tooltip support remain available.", "Matched localized final-boss arrivals to existing per-boss soundtrack overrides using documented zone keys, retaining native final classification and replay protection.", "Fixed empty sample party frames surviving native UI restoration and setup controls reappearing after Demo teardown.", "Updated feature/audio documentation and added a native UI verification matrix and API capability review. Stationary native checks and 54 behavioral scenarios passed; combat, multiplayer and broader display coverage remain unverified." } },
	{ v = "1.44", summary = "", items = { "Added normalized Megalovania as an optional final-boss arrival soundtrack, with per-boss overrides for all twelve guide finals and duplicate/reload protection.", "Kept achievements hidden and fully inactive behind a WIP gate. Added a provenance-aware fallback observation framework, separating revive attempts and self-reported credit from confirmed game data.", "Added normalized CSGO Okay Let’s Go to match-start songs. Built the dormant unofficial side-achievement catalog and menu, including optional Azeroth Stats goals; no achievement UI or tracking is enabled in this WIP release.", "Combined player and teammate death sounds into one shared selection matrix, including Roblox for both. Added Halo \"Game Over\" exclusively for final defeat.", "Added play/stop previews where supported and prevented overlapping previews on legacy clients without StopSound.", "Reduced Cena bass by 3 dB at 120 Hz. Applied a one-time +6.02 dB Hitmarker boost before peak limiting; all other sounds retain the standard mix." } },
	{ v = "1.43", summary = "", items = { "Added Cena and pillar man jojo as optional match-start songs, plus To Be Continued JoJo for victory. All three retain their original filenames and are normalized to the existing audio mix.", "Stabilized legendary luck graph axes and added starting/current luck with encouragement based on the measured relative improvement in estimated legendary odds. Live luck continues to follow character stats; mid-run tracking is labeled honestly." } },
	{ v = "1.42", summary = "", items = { "Promoted Legendary luck out of WIP, retaining its percentage/graph GUI and removing investment/status phrases. Added an always-available green setup preview and verified shared resizing while respecting its optional live-display toggle.", "Fixed Lua 5.0 clock-overlay errors caused by unavailable math.huge. The same compatibility issue in numeric profile import validation is fixed, with legacy-constant regression coverage." } },
	{ v = "1.41", summary = "", items = { "Temporary choice overlays now corroborate choosing with a stopped interpolated run clock, and wait for playing plus a clock restart before normal restoration. Ordinary pause cannot open the overlay; missing clocks retain phase-only compatibility and stalled closing clocks have a bounded safety timeout.", "Added bracketed Talent/Gear source labels to damage-meter spell rows using documented source categories and origins.", "Added an optional, movable Legendary luck [WIP] panel with current luck, estimated legendary card/amulet chances, model curves and the requested trend phrases. The prototype uses the supplied approximation and is disabled by default." } },
	{ v = "1.40", summary = "", items = { "Replaced the main splash/settings tabs with a five-module hub: Chat Mods, Sound Effects, User Interface, Gameplay and Misc. Each category has an on/off switch and its own settings page.", "Module switches retain preferences; disabling User Interface restores the native HUD and preserves the saved custom layout, including muted elements, for re-enabling. Exports/autosave retain paused preferences and profile imports cannot bypass a disabled module.", "Removed diagnostics/compatibility screens, their slash commands, and all installed-addon management controls. Moved accessibility settings to Misc.", "Removed the separate load-in/game-launch song option. One match-start selector now plays on first movement only; existing enabled early-load selections migrate to it." } },
	{ v = "1.39", summary = "", items = { "Restored the seven original user-supplied MP3 filenames and updated playback paths and normalization records without changing the normalized audio.", "Combat text now retains one shared forward-only insertion row across quiet/empty periods. Normal hits and highlights continue where the prior line left off, wrap bottom-to-top, and never repack surviving lines backward. Resizing safely wraps the retained cursor into the new bounds." } },
	{ v = "1.38", summary = "", items = { "Demoted weak crits now use normal white text, normal font size and no critical suffix or rightward effect. Highlight selection checks both the source baseline and the player’s learned overall damage.", "Reserved normal-log capacity so critical highlight bursts cannot consume every row and erase ordinary damage.", "Added a separate optional Load-in song (Move to Start) selector. It plays once on entering the ready screen, independently of the existing Ready → Playing start-song option, with protection against repeated polling and temporary missing phase data." } },
	{ v = "1.37", summary = "", items = { "Added normalized GTA V Wasted exclusively to final match-loss choices, separate from recoverable player/teammate death audio. Future audio additions require normalization and measured-asset checks before release.", "Added an independent teammate death selector with Roblox and Same as player, plus an optional GTA San Andreas victory sound that plays once per win.", "Leveled all 13 MP3 assets to a common -12 LUFS target (original Whip Crack + 1.5 dB), with limiting and endpoint fades. Decoded true peaks remain below -1 dBTP; included reproducible build-time normalization and asset checks.", "Added Duck Toy to player/teammate death sound choices, The Price Is Right losing horn to a separate match-loss group, and Kit Kit Kit as an optional match-start song.", "Ordinary death sounds wait briefly for the run result; confirmed defeat clears them and plays only the selected game-over alert. Start songs play once on Ready → Playing; victories, leaving and historical end screens do not replay loss audio.", "Combat highlights now learn per-source damage and critical-hit frequency, blending baselines each minute. Routine repeated crits remain in the downward log; rare or unusually strong hits use the rightward highlight rows. Learning resets per run and is bounded to 64 recent sources.", "Combat text animates every rendered UI frame, with cached, UTF-8-safe binary-search text fitting.", "Sound events now offer one selected sound or Off. Small speaker icons beside each option replace standalone preview buttons; added the supplied Gotcha sample for boss/guardian/lair kills.", "Trimmed the Zelda chest sound to its final four-note phrase (about 2.5 seconds).", "Added raw death-notification, confirmed corpse-anchor and authoritative boss/guardian counter fallbacks for kill sounds, with cross-source deduplication and silent historical initialization." } },
	{ v = "1.36", summary = "", items = { "Normal combat hits now stack downward without horizontal drift. Crits have their own top-to-bottom row cursor, fading right within bounds; normal rows avoid active crits and wrapping clears the prior crit before reuse.", "Fixed both optional boss/guardian/lair-owner kill sounds to use confirmed game death banners, independently of visible announcements. Deduplicated callback and polling delivery; loading historical banners does not replay old kills." } },
	{ v = "1.35", summary = "", items = { "Fixed build refreshes reopening green handles during Demo; editor previews and demo previews now have separate predicates.", "Encounter clicks now wait for authoritative target updates instead of cycling against stale server data; failed restoration is checked by spawn ID.", "Normal Explosive Orbs are discovered through living world anchors. Their encounter rows show real target/unit health when available and explicitly report unavailable health otherwise.", "Removed the unused combat popup pool/animation. Large-hit emphasis now uses the same bounded rainfall rows; renamed its setting and translated the new labels in all six supported locales.", "Explosive Orb takes first encounter-bar priority and reserves Skull ahead of bosses.", "Combat text uses separate downward tiers with rightward drift; tier reuse retires the prior hit.", "Demo mode hides all editor handles and restores them afterward. Grid choices are now 8/16/32/64; the compass is included in fresh setup defaults and remains editable on older profiles.", "Damage meters now request actor-level credits and combine each owner's pet/summon attacks without folding them into player spell rows.", "Player buffs above the frame use larger icons while retaining two-row bounds and collision checks.", "Removed duplicate guardian/lair waypoints. Encounter bars exclude ordinary elites, and clicks verify the exact hostile encounter ID instead of targeting by name.", "Compass and minimap share a per-frame moving-encounter position query. Active guardians join boss tracking; unavailable coordinates clear instead of retaining a stale marker.", "Selection screens temporarily show a horizontal item row beneath the native spell strip, sized from the supplied reference. Normal hidden/muted state, split/joined layout, sizing, orientation and scale remain unchanged and restore on exit.", "Exempted native minimap chrome from generic child clipping and released suppressed textures; restored the moon, top-right controls and full zoom buttons above the square ring.", "Attached local time now stays directly beneath the minimap border through layout rebuilds, using scale-correct spacing. Detached clocks retain their own positions." } },
	{ v = "1.34", summary = "", items = { "Combat log mode now suppresses native CombatDamage numbers and restores the original setting on exit/logout. Added native-number retention, all-enemy icons/critical hits, and boss-only damage modes, with an optional accompanying log.", "Build hover uses exact spell hyperlinks or matching real spellbook descriptions before an explicit unavailable message. Pregame cooldown labels read the actual starting spell/racial payload and show reported remaining time or the full interval without a fake countdown.", "Removed minimap rim clamping: points stay at reported world positions and disappear outside range. Bosses use their raid icons and names. Known pregame positions are dimmed; absent future coordinates are never fabricated.", "Added an optional rail/free-marker compass with Boss, Lair and Chest filters. Docked Build along the lower screen edge and Stats at the upper-right during card choices, with on-top tooltips and exact anchor restoration.", "Lowered only the square minimap body beneath its native title; the round-map anchors restore unchanged. Refined the stored-level button with a restrained interior glow, bronze gradient and contained count, without hover enlargement.", "Added shared region containment for movable elements and text truncation after minimum-font fitting. Tiny saved sizes respect element minimums; fitted tally dimensions are retained across later placement passes.", "Reserved explicit icon and glyph space for combat rows and popups, sanitized multiline hit names, and suppressed overflow at the same bounds used by green handles.", "Made Stats start at the damage meter’s 230 × 170 size, with internal scrolling, per-stat visibility grouped in its right-click menu, and live combined or pre-run Default + Bonus display.", "Added optional placement of the run-clock location and Normal/Heroic label above the time; either position stays inside the clock frame.", "Added corner-drag resizing for movable HUD elements, with persisted scales and linked build-row sizing. Split spell and jewelry rows now have independent visibility and optional matched icon sizes.", "Replaced the stats placeholder with live documented character-pane totals, current/max HP and aggregate shield, racial information, and active buff timers. Item, spell and racial bonuses are not added twice.", "Removed the redundant tooltip-width footer and stored-level checkbox. Stored levels follow the game setting; the addon no longer changes it. Added an XP-border visibility option for either orientation.", "Removed the optional replacement switches from UI settings. Added Go back to vanilla directly below Toggle UI Settings to reset positions, restore all native HUD parts (including stored level-ups), disable custom HUD replacements and overlays, and lock the editor. Reopening the editor explicitly resumes the custom HUD.", "Removed minimap button gathering, directional sorting and the independent movable collection box for both map shapes. Saved collection settings are retired, and buttons stay around the minimap.", "Fresh installs enable all managed custom HUD elements at their default positions, replacing the corresponding game UI. Existing saved layouts retain their choices.", "Replaced the visible element-state list and preset sidecar with a compact grid, Demo On/Off, Reset All and Done panel. Right-click green move boxes for individual settings.", "Confined combat-text popups and their text to the movable combat box; falling hits expire at its edges rather than the screen bottom.", "Removed the extra gap beneath the cache location/difficulty heading and kept horizontal counters inside the element bounds." } },
	{ v = "1.33", summary = "", items = { "Attached player and party buffs now use at most two rows within their portrait-and-health-bar width, including room for duration text. Rows avoid other visible HUD frames and the screen edges; party buffs also leave the player's buff area clear. Icons that cannot fit safely stay hidden until space is available, and detaching restores their original scale and mouse behavior." } },
	{ v = "1.32", summary = "", items = { "Moved encounter/boss DoTs to the far end of each health bar: right-aligned underneath horizontal bars and below the bottom of vertical bars, away from raid markers.", "Consolidated element metadata and derived native ownership, setup order, movable lists, companions and display anchors from the shared registry. Enabled/Disabled/Default governs replacement rendering and legacy checkbox transitions; old saved choices migrate without resetting onboarding.", "Split setup into onboarding, settings controls, editor state, unit-frame rendering, setup windows and settings-window modules while preserving manifest load order and saved profiles.", "Replaced unconditional profile polling snapshots with dirty tracking on edits, debounced saves and a logout flush.", "Added a checksum-pinned upstream Lua 5.0.3 compilation check to CI and explicit mock API methods with geometry validation.", "Consolidated translations into validated JSON dictionaries and generated Lua tables. Added complete Portuguese and Italian dictionaries, a language selector, translated dropdown choices and settings rows that grow for wrapped text.", "Added optional documented boss/guardian DoT attachments for native enemy nameplates, with the same timing data as modern plates; fresh installs keep this option off.", "Cache sounds now use the documented AZS_RUN.ck opened counter instead of disappearing cache entries. Teammate shield amounts remain unavailable without a client-provided absorb query.", "Added architecture, native-plate, state-authority, idle-autosave, translation-completeness and text-layout regression checks." } },
	{ v = "1.31", summary = "", items = { "Reviewed enemy-nameplate lifetime and projection handling: failed catalog reads cannot corrupt live records, pooled plates reuse their children, projections match anchor IDs and scale, and stale/missing projections hide immediately. Catalog failures back off instead of retrying every frame.", "Default restores native frame scaling, buff icon anchors, party-member anchors and XP-bar parenting/orientation; opening setup no longer immediately detaches a Default XP bar again. Explicit Disabled/Default choices prevent legacy native-HUD auto-adoption.", "Profiles retain additional HUD settings, minimap button placement and native-layout ownership. Exports have stable ordering; imports reject invalid types, non-finite/excessive geometry, incomplete sizes and cyclic anchors before applying.", "Cached unchanged display-template calculations and foreground registrations; reused profile snapshots during automatic saves. Absorb overlays stay inside health bars and allocate no controls while disabled.", "Low-health warnings repeat while health remains low, stop at death/recovery and retain the five-second minimum interval. Localized boss/Guardian tally labels and filled three missing French/German labels. Diagnostics no longer invent a stale installed version when metadata is unavailable.", "Added code-audit regressions, localized smoke checks and fail-fast module/startup checks; corrected the mock client's frame-name identity.", "Pending custom-profile edits flush at logout. Unavailable cache data no longer triggers a chest-opening sound.", "Demo controls now read Demo / On / Off followed by the right-click settings hint. Both minimap shapes retain the native map title and close button; enabling the minimap restores visible map opacity instead of caching setup's hidden state.", "Enabled immediately selects movable/custom mode and clears the old immovable flag. Attached party portraits align with the player's portrait center instead of frame padding. Selecting player buffs enables Buffs and makes above-frame rows grow upward.", "Unit-card refreshes keep native and New-school versions mutually exclusive during setup, including when changing only Target's style. Disabled custom player/target cards cannot reappear on a timer refresh.", "Removed the unsuccessful Move to begin foreground-layer workaround from 1.30. Enabled starting HUD values remain visible before movement." } },
	{ v = "1.30", summary = "", items = { "During Move to begin, register Slim Suite HUD, setup windows, move handles, and enabled managed native elements with the game's foreground overlay API; restore temporary registrations when leaving ready. Rendering above the native prompt still requires an in-game check.", "Enabled Kills / Gold / Cache is visible at Move to begin with starting values, and the ready timer stays at 00:00. Event-driven elements remain hidden when empty outside setup or Demo Mode." } },
	{ v = "1.29", summary = "", items = { "Kept the setup completion confirmation visible above the element menu. Mirror Target now calculates equal outer screen margins using the actual screen bounds." } },
	{ v = "1.28", summary = "", items = { "Disabled native HUD elements now remain hidden when their replacement updates. Fresh-install setup starts with both versions disabled, ready for a preset or manual setup. Done asks for confirmation and explains how to reopen setup with /slim setup.", "Reworked chat layout handling around the native dock: the real shared edit box keeps both width anchors, docked windows and controls scale together, setup preserves the selected tab, and Default restores native geometry and scaling. Disabled and muted states now cover the docked group and restore the input box correctly.", "General and Combat Log tabs share a baseline above the chat window and remain aligned after native dock updates; separately undocked chat tabs keep their own position.", "Announcements Disabled now hides both the game and Slim Suite versions; Enabled immediately hides the original, and Default restores it. Incoming banners and setup exit preserve the selected visibility.", "Native enemy-nameplate controls use the original 1.12 show/hide functions instead of the unsupported nameplateShowEnemies CVar. Regression checks cover nameplate restoration and buff layout without GetEffectiveScale." } },
	{ v = "1.27", summary = "", items = { "Added optional LEGO die death sound, hitmarker and whip-crack boss/Guardian/lair-owner kill sounds, and a Zelda-style cache-opening sound. Added an in-game preview button for each included sound so players can audition them before enabling.", "Setup rebuilds preserve party, minimap and clock choices; only selecting Default restores the game's settings. Updated the automated harness to load all addon modules and retain CVar changes.", "New installs open directly into setup with all native and Slim Suite elements Disabled; enabling an element immediately opens its controls and exposes its move handle.", "Added an attached Default profiles side panel with reserved slots for the profiles to be provided later.", "Choosing Default now explicitly restores the Blizzard/Aethus element and turns its game HUD visibility setting on; the movable replacement is turned off. The Level Up default restores the native Level Up button through the game's HUD API without displaying a chat command.", "Added a disabled-by-default low-health sound option using the supplied sound asset; it triggers at or below 30% health, is rate-limited to once every five seconds, and requests a one-second playback window.", "Added the Stat counter [WIP] setup placeholder and a read-only creator preset pathway that creates a numbered My Custom Profile copy before applying changes.", "Added native enemy-nameplate control and optional modern Slim Suite overlays, with a boss/lair-guardian filter, raid marks and documented boss/guardian debuff timers; ordinary enemy overlays are limited to 64 at a time.", "Added optional green absorb markers and numeric amounts to player and party health bars when the client exposes the data." } },
	{ v = "1.26", summary = "", items = { "Added a parenthetical hint beside Demo explaining that right-clicking an element name opens its settings." } },
	{ v = "1.25", summary = "", items = { "Toggle UI Settings enables movable Slim Suite elements by default on first use; users can set each element to Enabled, Disabled, or Default. The element name itself is non-clickable, with right-click opening its settings.", "Kills / Gold / Cache can show or hide the map name and named difficulty (Normal or Heroic 1–5) instead of a numeric multiplier.", "Removed the movable minimap button row's vertical/horizontal style control while retaining ring and top, bottom, left and right placement choices." } },
	{ v = "1.24", summary = "", items = { "Expanded HUD profiles with named save/apply/delete, single-layout import/export, and portable bundles for all named profiles; per-character layout support remains available.", "Added a display-aware recommended HUD preset action that repositions enabled elements using the selected aspect-ratio template while leaving Default and Disabled elements alone.", "Added encounter bar thickness and name-alignment controls, plus accessibility settings for high contrast, larger encounter names, and reduced floating-text motion.", "Added a diagnostics and compatibility view with addon/game versions, detected display template, saved profile count, and relevant Azeroth Survivors API availability.", "Slim Suite's patch version now appears in Settings, diagnostics, and the minimap-button tooltip." } },
	{ v = "1.23", summary = "", items = { "Automatic display layouts select among standard, ultrawide and portrait templates, keeping the reference HUD positions proportional to the viewport.", "Element sizes follow screen height with narrower-screen density adjustments; custom size multipliers remain relative to the automatic size.", "Custom locations saved with display bounds adapt proportionally across resolutions and restore when returning to the original display.", "Default-state elements remain controlled by the game.", "Slim Suite now follows the game client language for its setup, settings, edit controls, error log and common HUD labels in Spanish, French and German, with English fallback for other locales and untranslated text." } },
	{ v = "1.22", summary = "", items = { "Screen edges: dragging, saved positions, live boundary checks and the edit grid now share measured screen bounds, including the world viewport when the UI root occupies a smaller area. Scaled elements retain their visible bounds when placed against an edge." } },
	{ v = "1.19", summary = "More predictable UI setup, with native defaults preserved until you opt in.", items = { "Toggle UI Settings: every element now has Default, Enabled and Disabled states. Default restores the game's UI; Enabled uses Slim Suite's movable version; Disabled hides the element.", "Demo Mode: only elements enabled before Demo starts are previewed. Turning one off during a preview removes it from the demo.", "Element list: compacted the list and placed Reset All beside Done at the lower-right corner.", "Mirrored frames: Player and Target now use one Mirror Target setting and stay the same size and scale.", "Buffs and debuffs: attached auras wrap within the player's or target's frame bounds and grow outward from the selected edge." } },
	{ v = "1.17", summary = "Clearer demo and minimap details.", items = { "Demo Mode XP bar: purple progress steadily fills and returns to empty at 100%.", "Combat text: hits drift right more slowly and use smaller text.", "Square minimap: the map title stays visible above the map, its border fits below the title, and the map button joins the square edge layout.", "Transparent minimap: optional for round or square maps, with borders removed.", "Kills / Gold / Cache: shows the current map and the documented difficulty multiplier when available." } },
	{ v = "1.16", summary = "Demo Mode runs the whole interface like a real run, big hits pop, and raid marks show on the encounter bars.", items = { "Demo Mode:", "Four sample bosses and the target only ever lose health, then start again full.", "The party takes ticking damage, heals and big hits in short bursts, and the revive bar fills and starts over.", "Kills, gold and the cache price only climb, then start again from 0.", "The run clock counts up from a random time while the next boss counts down.", "Announcements of different lengths show every few seconds.", "The minimap shows sample caches and walking bosses with their marks.", "Starting it from the element list closes the list and shows only the small DEMO MODE box.", "Raid marks on the encounter bars: each boss or Guardian bar shows the same mark that is over its head and on the minimap.", "Combat text: crits and your biggest hits grow, drift to the right and slowly fall away. How much depends on how big they are next to your normal hits. This can be turned off in the combat text box's menu.", "Your buffs in the party: a row ends where your plate's health and mana bars end." } },
	{ v = "1.15", summary = "Buffs where you want them, a proper square map, and a tidier settings window.", items = { "Party buffs: your buffs and every party member's buffs sit above their plate, lined up with the portrait. Rows stop before the next party member and grow down when there are many. Friends' buffs can be turned off in the party's menu.", "Your buffs vs the target's: your buffs go in their own place or above, below, left or right of the player frame. The target's buffs and debuffs have their own side setting in the target's menu. Turning on Mirror target offers to match them.", "Square map: its ring now has the round map's colours and can never show on the round map. Slim Suite's gear sits on the ring, round or square, at the same distance as the game's own buttons.", "Minimap button row: optional (off by default). Its buttons are visible again instead of an empty grey box.", "Encounter bars: their green box fits on the screen again.", "Game settings: a part you turned off in the game's Interface settings (Run Clock, Boss Bars ...) gets Slim Suite's movable version once, automatically.", "Settings window: the UI page now only asks the \"Replace Default ... with Movable Version?\" questions; each element's other settings are in its own menu.", "Element list: two columns, can be dragged anywhere, and has Demo On / Off beside the grid." } },
	{ v = "1.14", summary = "One list for moving and switching everything.", items = { "Toggle UI Settings now always opens the element list: every element Slim Suite can change, each tagged Enabled, Disabled or Connected. The old move panel (Choose element, ALL?, Run setup again, centre lines) is gone.", "Grid sits on top of the list: a tick box and 16 / 32 / 64 / 128 blocks. Done at the bottom closes the list.", "Every element is listed, on or off. Turning one on in the list turns its feature on and gives it a green handle, including the combat text box.", "An element's own menu has just a Done button, which closes that menu." } },
	{ v = "1.13", summary = "Under the hood: Slim Suite is split into smaller files, and the unit frames react to the game's events.", items = { "Faster unit frames: the player and target cards, the party's lines, your party plate and the raid marks now update the moment health, power, level, target, party or marks change, instead of waiting for the next check. The checks still run, less often, as a safety net.", "Smaller files: the main file is split into five (basics, frames, edit mode, setup, commands). Nothing changes in the game, and the settings are kept. If you install by hand, replace the whole SlimSuite folder." } },
	{ v = "1.12", summary = "The damage meter looks like the game's own, the square map gets a gold ring, and Demo Mode is easier to use.", items = { "Damage meter: each pet or summon now has one line under its own name (Voidwalker, Imp ...), with all its attacks added together, as in the game's meter. Hover a pet's line to see its attacks. Lines are numbered, show amount (dps, share %), have bigger icons and coloured bars, and a \"proc\" tag on procs.", "Connected: in the setup list, an element that is joined to another (your player frame in the party, buffs on the player frame, a combined target) now says \"Connected\" instead of looking off. Hover the tag to see what it is joined to.", "Square map: a gold ring around it like the round map's border. The zoom buttons, the moon and other addons' buttons sit on the ring at the same places as on the round map, and the zone name sits on top of it.", "Clock: once the map is square or moved, Slim Suite's clock replaces the game's so it stays with the map.", "Your buffs in the party: they start at your plate's top-left corner and grow to the right. When a row is as wide as your plate, a new row starts above, so they never reach the next party member.", "Demo Mode: keeps your party's column or row. Slim Suite's menus close and a small \"DEMO MODE\" box with On and Off shows instead; Off brings the menus back." } },
	{ v = "1.11", summary = "Fixes and speed. Nothing new to learn.", items = { "Boss and Guardian kills: one counts as killed once it drops to 3% health or less (or dies). One that just leaves sight alive no longer counts.", "Setup: if something goes wrong during the setup, it closes cleanly and gives your interface back instead of leaving it half done. Resetting during the setup no longer leaves a gap.", "Mirror target: in Edit mode it no longer changes your setup choices.", "Jewelry names: rings and amulets show their real name, taken from the item itself. The item list is updated (39 items).", "Error log: only Slim Suite's own errors are kept. Errors from while the game was loading are kept too.", "Speed: world markers, floating text, boss bars, the meter and Edit mode do less work each second.", "Timers: starting or stopping a timer from inside another no longer skips or repeats one." } },
	{ v = "1.10", summary = "Review fixes, a faster idle, saved layouts and new commands (/slim help).", items = {  } },
	{ v = "1.09", summary = "The right-click menu on any element is now the setup menu.", items = {  } },
	{ v = "1.08", summary = "Your buffs line up with your party plate.", items = {  } },
	{ v = "1.07", summary = "You first in the party, raid marks on frames, tooltip placement, and the XP bar keeps the game's border.", items = {  } },
	{ v = "1.06", summary = "Frame looks per frame, party layout and thin lines; previews only while editing.", items = {  } },
